package il.transit.core.calendar

import java.time.DayOfWeek
import java.time.LocalDate

/**
 * The days of the Jewish calendar that change public transport in Israel (Phase 10 D3, owner
 * decision 2). Muslim, Christian and Druze holidays are not covered. The dates are Israel's
 * (one day of yom tov) and come from [HolidaysData], generated by `tools/gen_holidays.py`.
 */
enum class Holiday(val kind: DayKind?) {
    ROSH_HASHANA_1(DayKind.NO_SERVICE),
    ROSH_HASHANA_2(DayKind.NO_SERVICE),
    YOM_KIPPUR(DayKind.NO_SERVICE),
    SUKKOT(DayKind.NO_SERVICE),
    CHOL_HAMOED_SUKKOT(DayKind.REDUCED),
    SHMINI_ATZERET(DayKind.NO_SERVICE),
    PESACH_1(DayKind.NO_SERVICE),
    CHOL_HAMOED_PESACH(DayKind.REDUCED),
    PESACH_7(DayKind.NO_SERVICE),
    SHAVUOT(DayKind.NO_SERVICE),

    /** In the table for the moving rule only; transport runs as usual. */
    YOM_HASHOAH(null),

    /** In the table for the moving rule only; Yom HaAtzmaut starts in its evening. */
    YOM_HAZIKARON(null),
    YOM_HAATZMAUT(DayKind.REDUCED),
}

/** What a day means for buses and trains. Each rule has its source on the constant. */
enum class DayKind {
    /**
     * No buses or trains until the evening after: the Jewish days of rest of the Law and
     * Administration Ordinance, 1948 (§ 18A) — Rosh Hashana 1–2, Yom Kippur, Sukkot, Shmini
     * Atzeret, Pesach first and seventh day, Shavuot; MOT and Israel Railways run no service on
     * them, as on Shabbat.
     */
    NO_SERVICE,

    /**
     * The day before a [NO_SERVICE] day: buses run a Friday timetable and trains stop in the
     * afternoon (MOT and Israel Railways holiday notices, published before each holiday on gov.il
     * and rail.co.il).
     */
    EVE,

    /** Erev Yom Kippur: service ends earlier than on other eves (Israel Railways' Yom Kippur notice: last trains around midday). */
    YOM_KIPPUR_EVE,

    /** Yom HaAtzmaut and Chol HaMoed: "reduced service, check the times" (owner decision 2, 2026-10-12). */
    REDUCED,
}

/** A day of the table: its [kind] and the [holiday] it is (or, for an eve, the holiday that starts in its evening). */
data class HolidayDay(val date: LocalDate, val kind: DayKind, val holiday: Holiday)

object Holidays {
    const val FIRST_YEAR = HolidaysData.FIRST_YEAR
    const val LAST_YEAR = HolidaysData.LAST_YEAR

    /** The holiday on [date] itself, or null (also outside the table). */
    fun holiday(date: LocalDate): Holiday? = HolidaysData.DAYS[date]

    /**
     * What [date] means for transport, or null for an ordinary day. A no-service day wins over
     * being an eve (Rosh Hashana 1 is followed by day 2), an eve over Chol HaMoed (Hoshana
     * Rabba, the day before Shmini Atzeret, and Pesach's sixth day).
     */
    fun day(date: LocalDate): HolidayDay? {
        val own = holiday(date)
        if (own?.kind == DayKind.NO_SERVICE) return HolidayDay(date, DayKind.NO_SERVICE, own)
        val next = holiday(date.plusDays(1))
        if (next?.kind == DayKind.NO_SERVICE) {
            val kind = if (next == Holiday.YOM_KIPPUR) DayKind.YOM_KIPPUR_EVE else DayKind.EVE
            return HolidayDay(date, kind, next)
        }
        val kind = own?.kind ?: return null
        return HolidayDay(date, kind, own)
    }

    /** No buses or trains on [date] until its evening: Shabbat or a [DayKind.NO_SERVICE] day. */
    fun restDay(date: LocalDate): Boolean = date.dayOfWeek == DayOfWeek.SATURDAY || day(date)?.kind == DayKind.NO_SERVICE

    /** Service on [date] ends in the afternoon: a Friday, or the day before a rest day. */
    fun shortDay(date: LocalDate): Boolean = !restDay(date) && (date.dayOfWeek == DayOfWeek.FRIDAY || restDay(date.plusDays(1)))

    /** The table covers [date]'s year. */
    fun covers(date: LocalDate): Boolean = date.year in FIRST_YEAR..LAST_YEAR

    /**
     * Settings says "Holiday table out of date: update the app" from the table's last year on
     * (owner decision 2): the next autumn's dates are missing from then.
     */
    fun outOfDate(today: LocalDate): Boolean = today.year >= LAST_YEAR
}
